import { Component, For, JSX, mergeProps, ParentComponent, Show, splitProps, untrack } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { CardFrame } from "#core/ui-next/components/card-frame.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { HSlot, VSlot } from "#core/ui-next/components/slot.jsx";
import {
	Tooltip,
	TooltipBaseProps,
	TooltipHorizontalPosition,
	TooltipVerticalPosition,
} from "#core/ui-next/components/tooltip.jsx";
import { isMobile } from "#core/ui-next/services/view-experience.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import { LeaderWithRibbon } from "#base/ui-next/components/leader-with-ribbon.jsx";
import {
	SpreadsheetProps,
	useVictoriesScreenContext,
	VictoryRowPlayer,
	VictoryRulesTooltipProps,
	VictoryTabType,
} from "#base/ui-next/screens/victories/victories-screen-model.js";

interface VictoryTabBaseProps extends JSX.HTMLAttributes<HTMLDivElement> {
	title: string;
	titleColorClass: string;
	header: string;
	rules: string;
	background: string;
	targetScore: number;
	preScrollContent?: JSX.Element;
	showPointsNeeded?: boolean;
	alternatePointsContent?: JSX.Element;
	pointsNeededText?: string; //TODO: Can be made not optional once we figure out the terminology for each tab (i.e. tourism vs GDP, etc)
}

interface VictoryRowProps extends JSX.HTMLAttributes<HTMLDivElement> {
	class?: string;
	rowId: number;
	columnClassOverride?: string;
	playerInfo: VictoryRowPlayer;
	divider: boolean;
	rowType: VictoryTabType;
	skipContentColumn?: boolean;
	skippedFirstContent?: JSX.Element;
	showTooltip?: boolean;
	omitBottomLine?: boolean;
	activateInfo?: (playerId: PlayerId) => void;
}

interface SpreadsheetTooltipProps extends TooltipBaseProps {
	data: SpreadsheetProps;
}

//region VICTORY TAB BASE
export const VictoryTabBase: Component<VictoryTabBaseProps> = (props) => {
	const isSmallScreen = useIsSmallScreen();
	const mergedProps = mergeProps({ showPointsNeeded: true }, props);

	return (
		<VSlot
			name={Locale.compose(props.title)}
			class="relative bg-cover bg-no-repeat h-full flex flex-col items-center w-full"
			style={{ "background-image": `url(${props.background})` }}
		>
			<Show when={!isSmallScreen()}>
				<div class={`absolute ${isMobile() ? "-top-16" : "-top-14"} victories-header`}>
					<div class="font-body text-body text-xs self-center">
						<L10n.Compose text={props.header} />
					</div>
				</div>
			</Show>
			<div class="flex flex-row absolute -mt-6 ml-2 w-full victories-point-goal-line">
				<div
					class={`victories-military-cols-1-and-2 font-title uppercase font-bold ${props.titleColorClass} ${!isSmallScreen() ? "text-lg" : "text-2xl"}`}
				>
					<div role="heading">
						<L10n.Compose text={props.title} />
					</div>
				</div>
				<Show
					when={mergedProps.showPointsNeeded}
					fallback={props.alternatePointsContent}
				>
					<div class="victories-military-col-4 font-title text-xl text-white flex flex-row">
						<div class="h-full w-2" />
						<div class="flex-1 self-center">
							<Show
								when={props.targetScore != -1}
								fallback={
									<Tooltip.Text text={Locale.stylize("LOC_VICTORY_NOVICTORIES_TOOLTIP")}>
										<div class="self-center">-</div>
									</Tooltip.Text>
								}
							>
								<div class="self-center">{Locale.toNumber(props.targetScore)}</div>
							</Show>
						</div>
					</div>
					<div class="victories-military-col-3 font-title text-sm uppercase flex flex-row">
						<div class="w-full self-center">
							<div class="self-start ml-2">
								<L10n.Compose text={props.pointsNeededText ?? "LOC_VICTORY_POINTS_NEEDED_TO_WIN"} />
							</div>
						</div>
					</div>
				</Show>

				<div class="flex flex-row">
					<div class="self-center">
						<VictoryRulesTooltip
							initialHPosition={TooltipHorizontalPosition.LEFT}
							initialVPosition={TooltipVerticalPosition.TOP}
							class="self-center"
							tooltipText={props.rules}
							titleText={props.title}
							titleClass={props.titleColorClass}
						/>
					</div>
				</div>
			</div>
			<div class="w-full h-4" />
			{props.preScrollContent}
			<ScrollArea
				class="shrink mb-2 flex-auto w-full"
				useProxy={true}
				reserveSpace={true}
			>
				<div class="flex flex-col">{props.children}</div>
			</ScrollArea>
		</VSlot>
	);
};
//#endregion

//region VICTORY HEADER
export interface VictoryHeaderProps extends JSX.HTMLAttributes<HTMLDivElement> {
	showDividersAroundChildren?: boolean;
	childContainerPosition?: "center" | "end";
	skipContentColumn?: boolean;
	hideContentColumnDivider?: boolean;
}
export const VictoryHeader: Component<VictoryHeaderProps> = (props) => {
	const mergedProps = mergeProps({ showDividersAroundChildren: true, childContainerPosition: "center" }, props);
	return (
		<div class="flex flex-row victories-military-bottom-line h-14 w-full">
			<div class="victories-military-col-1 font-title text-sm fxs-header uppercase self-center">
				<div>
					<L10n.Compose text="LOC_GENERIC_RANK" />
				</div>
			</div>
			<div class="victories-military-col-2 self-center" />
			<div
				class="victories-military-col-4 flex flex-row"
				classList={{ "victories-military-left-line-header": mergedProps.showDividersAroundChildren }}
			>
				<div class="w-full font-title text-sm fxs-header uppercase flex flex-row">
					<div class="self-center w-full text-center font-fit-shrink">
						<L10n.Compose text="LOC_GENERIC_SCORE" />
					</div>
				</div>
			</div>
			<Show when={!props.skipContentColumn}>
				<div
					class="victories-military-col-3 font-title text-sm"
					classList={{
						"victories-military-left-line-header":
							mergedProps.showDividersAroundChildren && !mergedProps.hideContentColumnDivider,
						"self-end": mergedProps.childContainerPosition === "end",
					}}
				>
					{props.children}
				</div>
			</Show>
		</div>
	);
};
//#endregion

//region VICTORY ROW
interface VictoryRowPlayerDisplayProps {
	rowType: VictoryTabType;
	playerInfo: VictoryRowPlayer;
	rowId: number;
	class?: string;
	columnClassOverride?: string;
	showRelationships: boolean;
	activateInfo?: (playerId: PlayerId) => void;
}
const VictoryRowPlayerDisplay: Component<VictoryRowPlayerDisplayProps> = (props) => {
	const ctx = useVictoriesScreenContext();

	const onMouseEnter = () => {
		ctx.highlightPlayer(props.playerInfo.playerId, props.rowType);
	};
	const onMouseLeave = () => {
		ctx.unHighlightPlayer(props.playerInfo.playerId, props.rowType);
	};
	const onFocus = () => {
		ctx.focusPlayer(props.playerInfo.playerId, props.rowType);
	};
	const onBlur = () => {
		ctx.unFocusPlayer(props.playerInfo.playerId, props.rowType);
	};

	const columnClass = untrack(() => `victories-${props.columnClassOverride ?? "military"}`);

	const isSmallScreen = useIsSmallScreen();

	return (
		<Activatable
			class={`${columnClass}-cols-1-and-2 victories-row-${props.rowId} relative flex flex-row`}
			onMouseEnter={onMouseEnter}
			onMouseLeave={onMouseLeave}
			onFocus={onFocus}
			onBlur={onBlur}
			autoFocus={props.rowId == 0}
			onActivate={() => props.activateInfo?.(props.playerInfo.playerId)}
			audioComponentAlias="PlayerRow"
		>
			<div
				class={`absolute inset-0 bg-cover bg-no-repeat duration-150 ease-out ${props.playerInfo.highlighted() || props.playerInfo.focused() ? "opacity-60" : "opacity-30"}`}
				style={{
					"background-image": `url(blp:${props.playerInfo.playerIsMet ? props.playerInfo.playerBanner : "bn_deluxe"})`,
					"transition-property": "opacity",
				}}
			/>

			<div class="absolute inset-0 flex flex-row">
				<div class={`flex flex-row ${columnClass}-col-1 justify-center`}>
					<div
						class={`self-center ${props.playerInfo.playerId == GameContext.localPlayerID ? "text-white" : ""}`}
					>
						{props.rowId}
					</div>
				</div>
				<div class={`relative ${columnClass}-col-2 victories-military-left-line`}>
					<HSlot>
						<div class={props.playerInfo.playerId == GameContext.localPlayerID ? "mt-2 mx-2" : "mx-2"}>
							<LeaderWithRibbon
								leaderId={
									props.playerInfo.playerIsMet ? props.playerInfo.playerId : PlayerIds.NO_PLAYER
								}
								size={28}
								omitFullRibbon={true}
								omitRelationshipIcon={
									props.playerInfo.playerId == GameContext.localPlayerID || !props.showRelationships
								}
							/>
						</div>
						<VSlot class="victories-military-player-vslot mt-7 flex-1">
							<Show
								when={Configuration.getGame().isAnyMultiplayer && props.playerInfo.playerName[0] == "["} // name starting with [ is a placeholder tag for a multiplayer online handle
								fallback={
									<div class={`text-white ${isSmallScreen() ? "text-xs" : ""}`}>
										<L10n.Stylize
											text={`${Locale.compose(props.playerInfo.playerIsMet ? props.playerInfo.playerName : "LOC_UI_UNMET_PLAYER_NAME")} ${Locale.compose(props.playerInfo.playerId == GameContext.localPlayerID ? "LOC_UI_RANKINGS_YOU" : "")}`}
										/>
									</div>
								}
							>
								<div class={`text-white ${isSmallScreen() ? "text-xs" : ""}`}>
									<L10n.Stylize
										text={`${Locale.compose(props.playerInfo.playerIsMet ? props.playerInfo.leaderName : "LOC_UI_UNMET_PLAYER_NAME")}  ${Locale.compose(props.playerInfo.playerId == GameContext.localPlayerID ? "LOC_UI_RANKINGS_YOU" : "")}`}
									/>
								</div>
								<div class={`text-white ${isSmallScreen() ? "text-xs" : ""} break-words`}>
									<L10n.Stylize
										text={`${Locale.compose(props.playerInfo.playerIsMet ? props.playerInfo.playerName : "")}`}
									/>
								</div>
							</Show>
							<div class="text-body">
								<L10n.Compose text={props.playerInfo.govType} />
							</div>
							<Show when={props.playerInfo.playerAtWarWith}>
								<div class="text-negative">
									<L10n.Compose text="LOC_TRADE_LENS_ROUTE_TYPE_WAR" />
								</div>
							</Show>
						</VSlot>
					</HSlot>
				</div>
			</div>
		</Activatable>
	);
};
export const VictoryRow: Component<VictoryRowProps> = (props) => {
	const mergedProps = mergeProps({ showTooltip: true }, props);
	const [playerDisplayProps] = splitProps(props, [
		"rowType",
		"playerInfo",
		"rowId",
		"class",
		"columnClassOverride",
		"activateInfo",
	]);
	const columnClass =
		// this is not used reactively so we don't need the warning
		// eslint-disable-next-line solid/reactivity
		props.columnClassOverride != undefined ? `victories-${props.columnClassOverride}` : "victories-military";

	// and neither is this
	// eslint-disable-next-line solid/reactivity
	const showRelationships = props.rowType == VictoryTabType.Military;

	return (
		<HSlot
			class={`pointer-events-auto min-h-32 duration-150 ease-out ${props.class} ${props.omitBottomLine ? "" : "victories-military-bottom-line"}`}
		>
			<Show
				when={mergedProps.showTooltip}
				fallback={
					<VictoryRowPlayerDisplay
						{...playerDisplayProps}
						showRelationships={showRelationships}
					/>
				}
			>
				<SpreadsheetTooltip data={props.playerInfo.spreadsheet}>
					<VictoryRowPlayerDisplay
						{...playerDisplayProps}
						showRelationships={showRelationships}
					/>
				</SpreadsheetTooltip>
			</Show>
			<div class={`flex flex-row ${columnClass}-col-4`}>
				<div
					class="h-full w-2"
					style={{ "background-color": props.playerInfo.scoreColor }}
				/>
				<div
					class="self-center flex-1"
					classList={{ "opacity-30": props.playerInfo.dimScore() }}
					style={{ "transition-property": "opacity" }}
				>
					<div class={"font-title bold text-xl self-center text-white"}>
						{Locale.toNumber(props.playerInfo.score)}
					</div>
				</div>
			</div>
			<Show
				when={!props.skipContentColumn}
				fallback={
					<Show when={props.skippedFirstContent}>
						<HSlot class={`${columnClass}-col-3 h-full flex-wrap relative}`}>
							{props.skippedFirstContent}
						</HSlot>
					</Show>
				}
			>
				<HSlot
					class={`${columnClass}-col-3 flex-wrap relative  ${props.divider ? "victories-military-left-line" : ""}`}
				>
					{props.children}
				</HSlot>
			</Show>
		</HSlot>
	);
};
//#endregion

//region RULES TOOLTIP
export const VictoryRulesTooltip: Component<VictoryRulesTooltipProps> = (props) => {
	const model = useVictoriesScreenContext();

	return (
		<Tooltip
			initialHPosition={props.initialHPosition}
			initialVPosition={props.initialVPosition}
		>
			<Tooltip.Trigger>
				<Activatable
					class={`size-${props.size ?? 8} bg-no-repeat bg-cover`}
					style={{ "background-image": "url(blp:icon_info)" }}
					disableFocus={props.disableFocus ? props.disableFocus : !model.tooltipToggle}
					autoFocus={model.tooltipToggle}
				/>
			</Tooltip.Trigger>
			<Tooltip.Content>
				<Tooltip.Frame>
					<div class="items-center">
						<div class={`font-title text-xs uppercase self-center ${props.titleClass}`}>
							<L10n.Compose text={props.titleText} />
						</div>
						<div class="font-title text-xs text-secondary uppercase self-center">
							<L10n.Compose text="LOC_VICTORY_RULES_TOOLTIP_TITLE" />
						</div>
						<div class="font-body text-xs text-primary self-center mb-4">
							<L10n.Compose text="LOC_VICTORY_RULES_TOOLTIP_POINTS" />
						</div>
						<CardFrame class="mb-4 max-w-192">
							<L10n.Stylize
								class="mx-4 my-4"
								text={props.tooltipText}
							/>
						</CardFrame>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};
//#endregion

//region SPREADSHEET TOOLTIP
export const SpreadsheetTooltip: ParentComponent<SpreadsheetTooltipProps> = (props) => {
	const [local, _other] = splitProps(props, ["children", "class"]);

	return (
		<Tooltip
			initialHPosition={TooltipHorizontalPosition.CENTER}
			initialVPosition={TooltipVerticalPosition.TOP}
		>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Show when={props.data.metPlayer}>
				<Tooltip.Content class={local.class}>
					<Tooltip.Frame>
						<div class={`items-center ${props.data.metPlayer ? "mb-4" : ""}`}>
							<div class="font-title-sm uppercase self-center fxs-header mb-2">
								<L10n.Compose text={props.data.title ? props.data.title : ""} />
							</div>
							<CardFrame class="mb-4">
								<div class="w-full h-3" />
								<For each={props.data.items}>
									{(sheetItem, index) => (
										<VSlot>
											<Show when={index() > 0}>
												<div class="relative mx-4 victories-tooltip-divider" />
											</Show>
											<HSlot class="victories-tooltip-spreadsheet-row min-h-8 font-body text-xs text-body ml-4 mr-4 justify-between">
												<div
													class="victories-tooltip-spreadsheet-player-id-block"
													role="heading"
												>
													<L10n.Compose text={sheetItem.name} />
												</div>
												<div>{Locale.toNumber(sheetItem.points)}</div>
											</HSlot>
										</VSlot>
									)}
								</For>
								<Show when={props.data.showTotal}>
									<VSlot>
										<div class="relative mx-4 victories-tooltip-divider" />
										<HSlot class="victories-tooltip-spreadsheet-row min-h-8 font-title-sm uppercase fxs-header mx-4 justify-between">
											<div
												class="victories-tooltip-spreadsheet-player-id-block"
												role="heading"
											>
												<L10n.Compose text="LOC_VICTORIES_TOOLTIP_TOTAL" />
											</div>
											<div>{Locale.toNumber(props.data.points)}</div>
										</HSlot>
									</VSlot>
								</Show>
							</CardFrame>
							<Show when={props.data.showTotal}>
								<CardFrame class="mb-4">
									<div class="w-full h-2" />
									<HSlot class="victories-tooltip-spreadsheet-row min-h-8 font-body text-xs text-body ml-4 mr-4 justify-between">
										<div
											class="victories-tooltip-spreadsheet-player-id-block"
											role="heading"
										>
											<L10n.Compose text="LOC_VICTORIES_TOOLTIP_LAST_TURN" />
										</div>
										<HSlot>
											<div>{props.data.lastTurnDelta > 0 ? "+" : ""}</div>
											<div>{Locale.toNumber(props.data.lastTurnDelta)}</div>
										</HSlot>
									</HSlot>
								</CardFrame>
							</Show>
						</div>
					</Tooltip.Frame>
				</Tooltip.Content>
			</Show>
		</Tooltip>
	);
};
//#endregion
